// Package agentusageview is the `:agent-usage` screen: the Claude Code
// sessions found on this machine.
//
// It reads transcripts' working directory and date only, never their content
// (internal/agentusage owns that guarantee).
package agentusageview

import (
	"github.com/charmbracelet/bubbles/spinner"
	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/agentusage"
	"github.com/anthnel/devdesk/internal/config"
	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// sessionRow is one table row. project is computed once, in Update, so a Cell
// never touches the file system or the environment.
type sessionRow struct {
	agentusage.Session
	project string // theme.FoldHome(Project), or "-" when unknown
}

// sessionListLoadedMsg carries one listing. gen drops an answer to a read that
// a newer one has superseded.
type sessionListLoadedMsg struct {
	gen     int
	root    string
	listing agentusage.Listing
	err     error
}

// level is the screen on view: the sessions, or the agents of one session.
type level int

const (
	levelSessions level = iota
	levelAgents
)

// Model is the agent usage view.
type Model struct {
	table   datatable.Model[sessionRow]
	spinner spinner.Model
	footer  sharedcomponents.FooterMessage

	// level says which table is on screen. The sessions table keeps its cursor
	// and filter while the agents level is open.
	level level
	// agentTable lists the agents of open.
	agentTable datatable.Model[agentRow]
	open       agentusage.Session
	// usage is the last parse of open, kept for what the footer says about it.
	usage agentusage.Usage
	// agentGen numbers the parses, as gen numbers the listings.
	agentGen int
	// agg reads the open session incrementally. Update owns it; a Cmd only
	// ever gets a copy of its Cursor (Rule 110). nil at the sessions level.
	agg *agentusage.Aggregate
	// reading is true while a read of agentGen is in flight: one at a time.
	reading bool
	// fullPending records a ctrl+r pressed during a read; the full read starts
	// when that read answers.
	fullPending bool
	// pollStopped says the poll chain ended (settled session, deleted
	// transcript): a late tick of the same generation starts nothing. A full
	// read clears it.
	pollStopped bool
	// agentsLoading says a full read is in flight (the footer spinner).
	agentsLoading bool
	// agentsErr says the most recent parse failed (a state, like loadErr).
	agentsErr bool
	// width and height are the last viewport size, for both tables.
	width, height int

	// gen numbers the reads; only the answer to the latest one is kept.
	gen     int
	loading bool
	// loadErr says the most recent read failed. It is a state rather than a
	// timed message so the empty-listing sentence cannot take its place.
	loadErr bool
	// root is the projects directory the last successful read listed.
	root    string
	omitted int
}

// New builds the view with its first read pending.
func New(_ *config.Config) Model {
	sp := spinner.New()
	sp.Spinner = spinner.Dot
	sp.Style = theme.SpinnerStyle()

	return Model{
		loading: true,
		spinner: sp,
		table: datatable.New(datatable.Config[sessionRow]{
			Columns: sessionColumns(),
			// The listing arrives newest first, which is the order wanted.
			SortColumn: -1,
		}),
		agentTable: datatable.New(datatable.Config[agentRow]{
			Columns: agentColumns(),
			// Opens as the tree (orchestrator, then sub-agents); `.` sorts by Total.
			SortColumn: -1,
		}),
	}
}

// Init starts the first read and the spinner.
func (m Model) Init() tea.Cmd {
	cmds := []tea.Cmd{listSessionsCmd(m.gen), m.spinner.Tick}
	if m.level == levelAgents {
		// Init cannot change the model: Update restarts the open session's chain.
		cmds = append(cmds, resumeCmd())
	}
	return tea.Batch(cmds...)
}
package agentusageview

import (
	"errors"
	"fmt"
	"io/fs"
	"math/rand"
	"os"
	"path/filepath"
	"reflect"
	"regexp"
	"strings"
	"sync"
	"testing"
	"time"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/agentusage"
	"github.com/anthnel/devdesk/internal/ui/testutil"
)

// Live updates, step 4 (DEVDESK-45): the poll chain (answer, wait pollInterval,
// read, answer...) and the rule that stops it. Option A of the plan:
// quietPeriod 5 min, a settled session or a deleted transcript ends the chain.
// Leave/resume (step 5) and the header's live/paused slot (step 6) are not here.

var ansiRe = regexp.MustCompile(`\x1b\[[0-9;]*m`)

// ── Helpers ──────────────────────────────────────────────────────────────────

// usageLine is one assistant transcript line for message msgID.
func usageLine(msgID, model string, in, out int) string {
	return fmt.Sprintf(`{"type":"assistant","uuid":"u-%[1]s","message":{"id":%[1]q,"model":%[2]q,"role":"assistant","stop_reason":"end_turn","content":[],"usage":{"input_tokens":%[3]d,"output_tokens":%[4]d,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}}}`,
		msgID, model, in, out)
}

// appendLine appends line and a newline to path.
func appendLine(t *testing.T, path, line string) {
	t.Helper()
	appendRaw(t, path, line+"\n")
}

func appendRaw(t *testing.T, path, s string) {
	t.Helper()
	f, err := os.OpenFile(path, os.O_APPEND|os.O_WRONLY|os.O_CREATE, 0o600)
	if err != nil {
		t.Error(err)
		return
	}
	defer func() {
		if err := f.Close(); err != nil {
			t.Error(err)
		}
	}()
	if _, err := f.WriteString(s); err != nil {
		t.Error(err)
	}
}

// subDir is the sub-agents directory of the copied session.
func subDir(parent string) string {
	return filepath.Join(strings.TrimSuffix(parent, ".jsonl"), "subagents")
}

// finishTester flips the fixture's one unfinished sub-agent (a02) to finished,
// so nothing keeps the session alive but the recency of its files.
func finishTester(t *testing.T, parent string) {
	t.Helper()
	p := filepath.Join(subDir(parent), "agent-a02.meta.json")
	raw, err := os.ReadFile(p)
	if err != nil {
		t.Fatal(err)
	}
	edited := strings.Replace(string(raw), `"finished":false`, `"finished":true`, 1)
	if edited == string(raw) {
		t.Fatal("the fixture's a02 meta no longer says finished:false")
	}
	if err := os.WriteFile(p, []byte(edited), 0o600); err != nil {
		t.Fatal(err)
	}
}

// ageAll sets every file of the session (and its directories) d in the past.
func ageAll(t *testing.T, parent string, d time.Duration) {
	t.Helper()
	when := time.Now().Add(-d)
	for _, root := range []string{parent, strings.TrimSuffix(parent, ".jsonl")} {
		err := filepath.WalkDir(root, func(p string, _ fs.DirEntry, err error) error {
			if err != nil {
				return err
			}
			return os.Chtimes(p, when, when)
		})
		if err != nil {
			t.Fatal(err)
		}
	}
}

// ticksOf keeps the poll ticks among msgs.
func ticksOf(msgs []tea.Msg) []usagePollTickMsg {
	var got []usagePollTickMsg
	for _, m := range msgs {
		if tk, ok := m.(usagePollTickMsg); ok {
			got = append(got, tk)
		}
	}
	return got
}

// runCmd runs cmd with a short poll interval and returns what it produced.
func runCmd(t *testing.T, cmd tea.Cmd) []tea.Msg {
	t.Helper()
	testutil.FastTimers(t, &pollInterval)
	return batchMsgs(t, cmd)
}

