	m, _, cmd := openedFixture(t)
	msg := firstDelta(t, cmd)

	m, msgs := answered(t, m, msg)

	ticks := ticksOf(msgs)
	if len(ticks) != 1 || ticks[0].gen != m.agentGen {
		t.Fatalf("want one tick of gen %d, got %+v", m.agentGen, ticks)
